import{_ as i,o,c as l,a4 as a}from"./chunks/framework.vNSRaLQv.js";const b=JSON.parse('{"title":"Lenovo Lucienne (5500U) 单 GPU 直通记录","description":"","frontmatter":{"title":"Lenovo Lucienne (5500U) 单 GPU 直通记录","date":"2026-07-19T00:00:00.000Z"},"headers":[],"relativePath":"posts/setup-notes.md","filePath":"posts/setup-notes.md"}'),r={name:"posts/setup-notes.md"};function t(s,e,n,u,c,d){return o(),l("div",null,[...e[0]||(e[0]=[a('<h1 id="lenovo-lucienne-5500u-单-gpu-直通记录" tabindex="-1">Lenovo Lucienne (5500U) 单 GPU 直通记录 <a class="header-anchor" href="#lenovo-lucienne-5500u-单-gpu-直通记录" aria-label="Permalink to &quot;Lenovo Lucienne (5500U) 单 GPU 直通记录&quot;">​</a></h1><h2 id="硬件" tabindex="-1">硬件 <a class="header-anchor" href="#硬件" aria-label="Permalink to &quot;硬件&quot;">​</a></h2><ul><li>笔记本: Lenovo</li><li>CPU: AMD Ryzen 5 5500U (Lucienne, Zen 2)</li><li>GPU: AMD Radeon Graphics (1002:164c), 仅此一张 GPU</li><li>存储: NVMe (Samsung)</li><li>Host OS: Debian 13 / Kernel 6.12.95</li></ul><h2 id="iommu-分组" tabindex="-1">IOMMU 分组 <a class="header-anchor" href="#iommu-分组" aria-label="Permalink to &quot;IOMMU 分组&quot;">​</a></h2><p>IOMMU Group 5 包含全部 9 个设备（需整体直通）:</p><ul><li>04:00.0 — VGA (GPU)</li><li>04:00.1 — Audio (HDMI)</li><li>04:00.2 — Encryption (PSP)</li><li>04:00.3 — USB</li><li>04:00.4 — USB</li><li>04:00.5 — Audio Coprocessor</li><li>04:00.6 — HD Audio</li><li>05:00.0 — SATA</li><li>05:00.1 — SATA</li></ul><h2 id="成果-2026-07-19" tabindex="-1">成果 (2026-07-19) <a class="header-anchor" href="#成果-2026-07-19" aria-label="Permalink to &quot;成果 (2026-07-19)&quot;">​</a></h2><h3 id="手动掉绑回绑测试成功" tabindex="-1">手动掉绑回绑测试成功 <a class="header-anchor" href="#手动掉绑回绑测试成功" aria-label="Permalink to &quot;手动掉绑回绑测试成功&quot;">​</a></h3><p><strong>关键验证</strong>: amdgpu 可以干净地卸载并重新加载，没有 error -22。</p><p>测试步骤（SSH 执行）:</p><ol><li>systemctl stop sddm</li><li>echo 0 &gt; /sys/class/vtconsole/vtcon0/bind</li><li>echo 0 &gt; /sys/class/vtconsole/vtcon1/bind</li><li>echo efi-framebuffer.0 &gt; /sys/bus/platform/drivers/efi-framebuffer/unbind</li><li>echo simple-framebuffer.0 &gt; /sys/bus/platform/drivers/simple-framebuffer/unbind</li><li>modprobe -r amdgpu → 成功</li><li>modprobe amdgpu → 成功，fb0 创建，无 error -22</li><li>echo 1 &gt; /sys/class/vtconsole/vtcon0/bind</li><li>echo 1 &gt; /sys/class/vtconsole/vtcon1/bind</li><li>systemctl start sddm → 屏幕恢复</li></ol><p>结论: 之前 VM 直通后的 error -22 不是 VBIOS 问题，是脚本不完整（缺 vtconsole/efifb 解绑）。</p><h2 id="当前配置" tabindex="-1">当前配置 <a class="header-anchor" href="#当前配置" aria-label="Permalink to &quot;当前配置&quot;">​</a></h2><h3 id="hook-脚本" tabindex="-1">Hook 脚本 <a class="header-anchor" href="#hook-脚本" aria-label="Permalink to &quot;Hook 脚本&quot;">​</a></h3><p>/etc/libvirt/hooks/qemu → 分发器，调用 /bin/vfio-startup.sh / vfio-teardown.sh</p><h3 id="grub" tabindex="-1">GRUB <a class="header-anchor" href="#grub" aria-label="Permalink to &quot;GRUB&quot;">​</a></h3><p>GRUB_CMDLINE_LINUX_DEFAULT=&quot;quiet amd_iommu=on iommu=pt pcie_acs_override=downstream,multifunction initcall_blacklist=sysfb_init&quot;</p><h3 id="vbios-文件" tabindex="-1">VBIOS 文件 <a class="header-anchor" href="#vbios-文件" aria-label="Permalink to &quot;VBIOS 文件&quot;">​</a></h3><ul><li>/usr/share/vgabios/vbios.bin — 55KB, 113-LUCIENNE-016 (Lenovo OEM, 本机提取)</li><li>/usr/share/vgabios/vbios_5500U.bin — 55KB, 113-LUCIENNE-019 (isc30 通用)</li><li>/usr/share/vgabios/AMDGopDriver_5500U.rom — 74KB GOP 驱动</li></ul><p>VM XML 当前使用: vbios.bin（OEM 版）</p><h3 id="vm-配置" tabindex="-1">VM 配置 <a class="header-anchor" href="#vm-配置" aria-label="Permalink to &quot;VM 配置&quot;">​</a></h3><ul><li>名称: win11, pc-q35-10.0, OVMF UEFI + Secure Boot</li><li>CPU: host-passthrough, 12 vCPU, 4GB RAM</li><li>直通: IOMMU group 5 全部 9 个设备 (managed=&#39;yes&#39;) <ul><li>04:00.0 GPU + romfile=vbios.bin</li><li>04:00.1 Audio + romfile=AMDGopDriver_5500U.rom</li><li>04:00.2-6 + 05:00.0-1 无 ROM</li></ul></li></ul><h3 id="vendor-reset" tabindex="-1">vendor-reset <a class="header-anchor" href="#vendor-reset" aria-label="Permalink to &quot;vendor-reset&quot;">​</a></h3><ul><li>gnif/vendor-reset, 添加 0x164c 到 AMD_NAVI10, DKMS 安装</li><li>udev: reset_method=device_specific</li><li>/etc/modules: vendor_reset</li></ul><h2 id="待办" tabindex="-1">待办 <a class="header-anchor" href="#待办" aria-label="Permalink to &quot;待办&quot;">​</a></h2><ol><li>[ ] 重启以应用 GRUB initcall_blacklist 参数</li><li>[ ] 启动 VM 测试完整直通（SSH 管理）</li><li>[ ] VM 停止后验证屏幕恢复</li><li>[ ] 如 Error 43: 添加 hypervisor 隐藏 args</li></ol>',26)])])}const m=i(r,[["render",t]]);export{b as __pageData,m as default};
